                                              << options_.rankId << ", shmName=" << desInfos[localIdx].shmName);
            return ACLSHMEM_DL_FUNC_FAILED;
        }
    }

    std::copy(desInfos.begin(), desInfos.end(), std::back_inserter(imports_));
    return ACLSHMEM_SUCCESS;
}

